package fetchall

import (
	"context"
	"errors"
	"sync"
)

// Result holds one successful operation output alongside its original position.
type Result struct {
	Index  int
	Output string
}

// Process runs operation concurrently on each input, limiting parallelism to
// concurrency. Results are returned in input order. Errors are aggregated
// and each individual error remains reachable via errors.Is / errors.As.
func Process(
	ctx context.Context,
	inputs []string,
	concurrency int,
	operation func(ctx context.Context, input string) (string, error),
) ([]Result, error) {
	if concurrency < 1 {
		return nil, errors.New("fetchall: concurrency must be at least 1")
	}
	if len(inputs) == 0 {
		return nil, nil
	}

	type entry struct {
		output string
		err    error
	}
	entries := make([]entry, len(inputs))
	sem := make(chan struct{}, concurrency)
	var wg sync.WaitGroup

	for i, input := range inputs {
		// Acquire a semaphore slot before launching.
		select {
		case sem <- struct{}{}:
		case <-ctx.Done():
			// Parent context cancelled; mark this and all remaining inputs
			// with the context error and stop launching.
			cause := context.Cause(ctx)
			if cause == nil {
				cause = ctx.Err()
			}
			for j := i; j < len(inputs); j++ {
				entries[j].err = cause
			}
			wg.Wait()
			return collect(entries)
		}

		wg.Add(1)
		go func(idx int, input string) {
			defer wg.Done()
			defer func() { <-sem }()
			out, err := operation(ctx, input)
			if err != nil {
				entries[idx].err = err
				return
			}
			entries[idx].output = out
		}(i, input)
	}

	wg.Wait()
	return collect(entries)
}

func collect(entries []entry) ([]Result, error) {
	var results []Result
	var errs []error

	for i, e := range entries {
		if e.err != nil {
			errs = append(errs, e.err)
		} else {
			results = append(results, Result{Index: i, Output: e.output})
		}
	}

	if len(errs) > 0 {
		return results, errors.Join(errs...)
	}
	return results, nil
}

package fetchall

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

func TestProcess_EmptyInputs(t *testing.T) {
	res, err := Process(context.Background(), nil, 1, nop)
	if res != nil || err != nil {
		t.Fatalf("expected (nil, nil), got (%v, %v)", res, err)
	}
	res, err = Process(context.Background(), []string{}, 5, nop)
	if res != nil || err != nil {
		t.Fatalf("expected (nil, nil), got (%v, %v)", res, err)
	}
}

func TestProcess_ConcurrencyTooSmall(t *testing.T) {
	res, err := Process(context.Background(), []string{"a"}, 0, nop)
	if res != nil || err == nil {
		t.Fatalf("expected error, got (%v, %v)", res, err)
	}
	res, err = Process(context.Background(), []string{"a"}, -1, nop)
	if res != nil || err == nil {
		t.Fatalf("expected error, got (%v, %v)", res, err)
	}
}

func TestProcess_AllSucceed(t *testing.T) {
	inputs := []string{"a", "b", "c"}
	res, err := Process(context.Background(), inputs, 2, func(_ context.Context, s string) (string, error) {
		return s + s, nil
	})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	want := []Result{{Index: 0, Output: "aa"}, {Index: 1, Output: "bb"}, {Index: 2, Output: "cc"}}
	if !eq(res, want) {
		t.Fatalf("got %v, want %v", res, want)
	}
}

func TestProcess_ResultsOrderedByIndex(t *testing.T) {
	// Even when operations complete out of order, results stay sorted.
	var starts sync.WaitGroup
	starts.Add(3)

	inputs := []string{"slow", "fast", "fastest"}
	res, err := Process(context.Background(), inputs, 3, func(_ context.Context, s string) (string, error) {
		switch s {
		case "slow":
			time.Sleep(50 * time.Millisecond)
		case "fast":
			time.Sleep(10 * time.Millisecond)
		}
		return s, nil
	})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	for i, r := range res {
		if r.Index != i {
			t.Fatalf("result at position %d has Index %d", i, r.Index)
		}
	}
}

func TestProcess_SomeFailures(t *testing.T) {
	inputs := []string{"ok", "fail1", "ok2", "fail2"}
	res, err := Process(context.Background(), inputs, 2, func(_ context.Context, s string) (string, error) {
		if s == "fail1" {
			return "", errors.New("err1")
		}
		if s == "fail2" {
			return "", errors.New("err2")
		}
		return s, nil
	})
	if err == nil {
		t.Fatal("expected an error")
	}

	// Both individual errors must be reachable.
	if !errors.Is(err, errors.New("err1")) {
		t.Error("err1 not reachable via errors.Is")
	}
	if !errors.Is(err, errors.New("err2")) {
		t.Error("err2 not reachable via errors.Is")
	}

	// Successful results returned, in order.
	if len(res) != 2 || res[0].Output != "ok" || res[1].Output != "ok2" {
		t.Fatalf("unexpected results: %v", res)
	}
}

func TestProcess_AllFailures(t *testing.T) {
	inputs := []string{"x", "y", "z"}
	e := errors.New("boom")
	_, err := Process(context.Background(), inputs, 1, func(_ context.Context, s string) (string, error) {
		return "", e
	})
	if err == nil {
		t.Fatal("expected an error")
	}
	if !errors.Is(err, e) {
		t.Error("individual error not reachable via errors.Is")
	}
}

func TestProcess_MaxConcurrency(t *testing.T) {
	var concurrent int32
	var maxConcurrent int32
	var mu sync.Mutex
	cond := sync.NewCond(&mu)

	inputs := []string{"a", "b", "c", "d", "e"}
	res, err := Process(context.Background(), inputs, 3, func(_ context.Context, s string) (string, error) {
		v := atomic.AddInt32(&concurrent, 1)
		mu.Lock()
		if v > maxConcurrent {
			maxConcurrent = v
		}
		mu.Unlock()
		// Stagger completion slightly to increase chance of overlap.
		time.Sleep(20 * time.Millisecond)
		atomic.AddInt32(&concurrent, -1)
		return s, nil
	})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if maxConcurrent > 3 {
		t.Fatalf("observed concurrency %d, want ≤ 3", maxConcurrent)
	}
	if len(res) != len(inputs) {
		t.Fatalf("got %d results, want %d", len(res), len(inputs))
	}
}

func TestProcess_RunsAllOnFailure(t *testing.T) {
	var ran int32
	inputs := []string{"a", "b", "c", "d"}
	_, err := Process(context.Background(), inputs, 2, func(_ context.Context, s string) (string, error) {
		atomic.AddInt32(&ran, 1)
		return "", errors.New("fail")
	})
	if err == nil {
		t.Fatal("expected error")
	}
	if n := atomic.LoadInt32(&ran); n != 4 {
		t.Fatalf("expected all 4 inputs to run, got %d", n)
	}
}

func TestProcess_ContextCancellationStopsLaunching(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	inputs := []string{"a", "b", "c", "d", "e", "f", "g", "h"}
	var started int32

	res, err := Process(ctx, inputs, 2, func(ctx context.Context, s string) (string, error) {
		atomic.AddInt32(&started, 1)
		// Block until ctx cancelled — this simulates a slow in-flight op.
		<-ctx.Done()
		return "", ctx.Err()
	})

	// Let some ops start, then cancel.
	time.Sleep(10 * time.Millisecond)
	cancel()

	if err == nil {
		t.Fatal("expected error")
	}
	// Context error must be reachable.
	if !errors.Is(err, context.Canceled) {
		t.Error("context.Canceled not reachable via errors.Is")
	}
	_ = res // Results may be nil since all ops failed
}

func TestProcess_CustomErrorTypeAggregation(t *testing.T) {
	type customErr struct{ msg string }

	inputs := []string{"a", "b"}
	_, err := Process(context.Background(), inputs, 1, func(_ context.Context, s string) (string, error) {
		return "", customErr{msg: s + "err"}
	})
	if err == nil {
		t.Fatal("expected error")
	}
	var ce customErr
	if !errors.As(err, &ce) {
		t.Error("customErr not reachable via errors.As")
	}
}

// nop is an operation that succeeds without transforming the input.
func nop(_ context.Context, s string) (string, error) {
	return s, nil
}

func eq(a, b []Result) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func init() {
	// Make sure fmt is used (the spec includes Output as string,
	// and we want a compile-time check that go vet is happy).
	_ = fmt.Sprintf
}

